mapper.select:
SELECT hm.id AS memo_id, op.incident_id, hm.operational_period_id AS op_id, hm.memo_target_type AS target_type, hm.memo_target_id AS target_id, hm.content, hm.created_by_account_id, hm.created_at, hm.version FROM handover_memo hm JOIN operational_period op ON op.id = hm.operational_period_id WHERE op.incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
AND hm.operational_period_id = #{opId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
AND hm.memo_target_type = #{memoTargetType}
AND hm.memo_target_id = #{memoTargetId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
ORDER BY hm.created_at DESC, hm.id ASC
